import torch

_DTYPE_MAP = {"int16": torch.int16, "int32": torch.int32, "int64": torch.int64}


def run(high, size, dtype):
    return torch.randint(high=high, size=tuple(size), dtype=_DTYPE_MAP[dtype])


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    sol = sol_outputs[0]
    high = inputs[0]
    size = tuple(inputs[1])
    dtype_str = inputs[2]
    dmap = {"int16": torch.int16, "int32": torch.int32, "int64": torch.int64}
    exp_dtype = dmap[dtype_str]
    if tuple(sol.shape) != size:
        return {"passed": False, "message": f"shape {tuple(sol.shape)} vs {size}", "metrics": {}}
    if sol.dtype != exp_dtype:
        return {"passed": False, "message": f"dtype {sol.dtype} vs {exp_dtype}", "metrics": {}}
    s = sol.detach().to("cpu")
    if not bool((s >= 0).all().item()):
        return {"passed": False, "message": "values below 0", "metrics": {}}
    if not bool((s < high).all().item()):
        return {"passed": False, "message": "values >= high", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
